#include <ctype.h>
#include <errno.h>
#include <inttypes.h>
#include <math.h>
#include <stdckdint.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum esito_calc {
    CALC_OK = 0,
    CALC_ERR_SINTASSI,
    CALC_ERR_OVERFLOW,
    CALC_ERR_DIV_ZERO,
    CALC_ERR_DOMINIO,
    CALC_ERR_RANGE
} esito_calc_t;

static esito_calc_t parsa_i64(const char *s, int64_t *out) {
    if (s == nullptr || *s == '\0' || isspace((unsigned char)*s)) { return CALC_ERR_SINTASSI; }
    char *end = nullptr;
    errno = 0;
    long long v = strtoll(s, &end, 10);
    if (errno == ERANGE) { return CALC_ERR_RANGE; }
    if (end == s || *end != '\0') { return CALC_ERR_SINTASSI; }
    *out = (int64_t)v;
    return CALC_OK;
}

static esito_calc_t esegui_op(const char *op, int64_t a, int64_t b, int64_t *out) {
    errno = 0;
    if (strcmp(op, "ADD") == 0) {
        return ckd_add(out, a, b) ? CALC_ERR_OVERFLOW : CALC_OK;
    } else if (strcmp(op, "SUB") == 0) {
        return ckd_sub(out, a, b) ? CALC_ERR_OVERFLOW : CALC_OK;
    } else if (strcmp(op, "MUL") == 0) {
        return ckd_mul(out, a, b) ? CALC_ERR_OVERFLOW : CALC_OK;
    } else if (strcmp(op, "DIV") == 0) {
        if (b == 0) { return CALC_ERR_DIV_ZERO; }
        if (a == INT64_MIN && b == -1) { return CALC_ERR_OVERFLOW; }
        *out = a / b;
        return CALC_OK;
    } else if (strcmp(op, "AREA") == 0) {
        if (a < 0 || b < 0) {
            errno = EDOM;
            const char *msg = strerror(errno);
            if (msg == nullptr || msg[0] == '\0') { return CALC_ERR_SINTASSI; }
            return CALC_ERR_DOMINIO;
        }
        return ckd_mul(out, a, b) ? CALC_ERR_OVERFLOW : CALC_OK;
    }
    return CALC_ERR_SINTASSI;
}

static esito_calc_t calcola_radice(const char *s, double *out) {
    if (s == nullptr || *s == '\0' || isspace((unsigned char)*s)) { return CALC_ERR_SINTASSI; }
    char *end = nullptr;
    errno = 0;
    double x = strtod(s, &end);
    if (errno == ERANGE || x == HUGE_VAL || x == -HUGE_VAL) {
        errno = ERANGE;
        return CALC_ERR_RANGE;
    }
    if (end == s || *end != '\0') { return CALC_ERR_SINTASSI; }
    if (x < 0.0) {
        errno = EDOM;
        return CALC_ERR_DOMINIO;
    }
    errno = 0;
    *out = sqrt(x);
    return CALC_OK;
}

static void stampa_errore(esito_calc_t es, int err_salvato) {
    const char *nome = "SINTASSI";
    if (es == CALC_ERR_OVERFLOW) { nome = "OVERFLOW"; }
    else if (es == CALC_ERR_DIV_ZERO) { nome = "DIV_ZERO"; }
    else if (es == CALC_ERR_DOMINIO) { nome = "DOMINIO"; }
    else if (es == CALC_ERR_RANGE) { nome = "RANGE"; }
    const char *enome = "0";
    if (err_salvato == EDOM) { enome = "EDOM"; }
    else if (err_salvato == ERANGE) { enome = "ERANGE"; }
    printf("ERRORE: %s (errno=%s)\n", nome, enome);
}

int main(void) {
    char riga[256], op[16], tok1[64], tok2[64], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", op) != 1) { continue; }
        if (strcmp(op, "SQRT") == 0) {
            if (sscanf(riga, "SQRT %63s %c", tok1, &extra) != 1) {
                stampa_errore(CALC_ERR_SINTASSI, 0);
                continue;
            }
            double r = 0.0;
            esito_calc_t es = calcola_radice(tok1, &r);
            int err_s = errno;
            if (es == CALC_OK) { printf("OK: %.2f\n", r); }
            else { stampa_errore(es, err_s); }
        } else {
            if (sscanf(riga, "%*15s %63s %63s %c", tok1, tok2, &extra) != 2) {
                stampa_errore(CALC_ERR_SINTASSI, 0);
                continue;
            }
            int64_t a = 0, b = 0, r = 0;
            esito_calc_t es = parsa_i64(tok1, &a);
            if (es == CALC_OK) { es = parsa_i64(tok2, &b); }
            if (es == CALC_OK) { es = esegui_op(op, a, b, &r); }
            int err_s = errno;
            if (es == CALC_OK) { printf("OK: %" PRId64 "\n", r); }
            else { stampa_errore(es, err_s); }
        }
    }
    return EXIT_SUCCESS;
}

#include <errno.h>
#include <inttypes.h>
#include <stdckdint.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum esito_pipe {
    PIPE_OK = 0,
    PIPE_ERR_APERTURA_IN,
    PIPE_ERR_MEM_BUF,
    PIPE_ERR_MEM_ARRAY,
    PIPE_ERR_APERTURA_OUT,
    PIPE_ERR_SCRITTURA
} esito_pipe_t;

typedef struct stats_risorse {
    size_t file_aperti;
    size_t file_chiusi;
    size_t blocchi_allocati;
    size_t blocchi_liberati;
} stats_risorse_t;

static bool somma_riga(const char *riga, int64_t *out) {
    const char *p = riga;
    int64_t acc = 0;
    while (*p != '\0') {
        char *end = nullptr;
        errno = 0;
        long long v = strtoll(p, &end, 10);
        if (end == p) { break; }
        if (errno == ERANGE || ckd_add(&acc, acc, (int64_t)v)) { return false; }
        p = end;
    }
    *out = acc;
    return true;
}

static esito_pipe_t elabora_pipeline(const char *file_in, const char *file_out, size_t n_righe, int guasto, stats_risorse_t *st) {
    esito_pipe_t esito = PIPE_ERR_SCRITTURA;
    FILE *fin = nullptr;
    char *buf = nullptr;
    int64_t *somme = nullptr;
    FILE *fout = nullptr;
    bool fout_creato = false;
    *st = (stats_risorse_t){};

    if (guasto == 1 || (fin = fopen(file_in, "r")) == nullptr) {
        esito = PIPE_ERR_APERTURA_IN;
        goto cleanup;
    }
    ++st->file_aperti;

    if (guasto == 2 || (buf = malloc(256)) == nullptr) {
        esito = PIPE_ERR_MEM_BUF;
        goto cleanup;
    }
    ++st->blocchi_allocati;

    size_t byte_arr = 0;
    if (guasto == 3 || ckd_mul(&byte_arr, n_righe, sizeof(*somme)) || (somme = malloc(byte_arr)) == nullptr) {
        esito = PIPE_ERR_MEM_ARRAY;
        goto cleanup;
    }
    ++st->blocchi_allocati;

    if (guasto == 4 || (fout = fopen(file_out, "w")) == nullptr) {
        esito = PIPE_ERR_APERTURA_OUT;
        goto cleanup;
    }
    ++st->file_aperti;
    fout_creato = true;

    for (size_t i = 0; i < n_righe; ++i) {
        if (fgets(buf, 256, fin) == nullptr || !somma_riga(buf, &somme[i])) {
            esito = PIPE_ERR_SCRITTURA;
            goto cleanup;
        }
    }
    if (guasto == 5) {
        esito = PIPE_ERR_SCRITTURA;
        goto cleanup;
    }
    for (size_t i = 0; i < n_righe; ++i) {
        if (fprintf(fout, "Riga %zu: %" PRId64 "\n", i, somme[i]) < 0) {
            esito = PIPE_ERR_SCRITTURA;
            goto cleanup;
        }
    }
    int rc_out = fclose(fout);
    fout = nullptr;
    ++st->file_chiusi;
    if (rc_out != 0) {
        esito = PIPE_ERR_SCRITTURA;
        goto cleanup;
    }
    esito = PIPE_OK;

cleanup:
    if (fout != nullptr) {
        fclose(fout);
        ++st->file_chiusi;
    }
    if (esito != PIPE_OK && fout_creato) {
        remove(file_out);
    }
    if (somme != nullptr) {
        free(somme);
        ++st->blocchi_liberati;
    }
    if (buf != nullptr) {
        free(buf);
        ++st->blocchi_liberati;
    }
    if (fin != nullptr) {
        fclose(fin);
        ++st->file_chiusi;
    }
    return esito;
}

static const char *nome_esito(esito_pipe_t e) {
    switch (e) {
        case PIPE_OK: return "OK";
        case PIPE_ERR_APERTURA_IN: return "ERR_APERTURA_IN";
        case PIPE_ERR_MEM_BUF: return "ERR_MEM_BUF";
        case PIPE_ERR_MEM_ARRAY: return "ERR_MEM_ARRAY";
        case PIPE_ERR_APERTURA_OUT: return "ERR_APERTURA_OUT";
        default: return "ERR_SCRITTURA";
    }
}

int main(void) {
    const char *f_in = "pipe_in_21_2.txt", *f_out = "pipe_out_21_2.txt";
    char riga[256], extra = '\0';
    int n_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr || sscanf(riga, "%d %c", &n_in, &extra) != 1 || n_in < 1 || n_in > 16) {
        return EXIT_FAILURE;
    }
    FILE *fp = fopen(f_in, "w");
    if (fp == nullptr) { return EXIT_FAILURE; }
    for (int i = 0; i < n_in; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr || fputs(riga, fp) == EOF) {
            fclose(fp); remove(f_in); return EXIT_FAILURE;
        }
    }
    if (fclose(fp) != 0) { remove(f_in); return EXIT_FAILURE; }

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        int g = 0;
        if (sscanf(riga, " %c", &extra) != 1) { continue; }
        if (sscanf(riga, "RUN %d %c", &g, &extra) != 1 || g < 0 || g > 5) { remove(f_in); return EXIT_FAILURE; }
        stats_risorse_t st = {};
        esito_pipe_t es = elabora_pipeline(f_in, f_out, (size_t)n_in, g, &st);
        printf("RUN %d: %s (file=%zu/%zu mem=%zu/%zu)\n", g, nome_esito(es), st.file_aperti, st.file_chiusi, st.blocchi_allocati, st.blocchi_liberati);
        if (es == PIPE_OK) {
            FILE *fo = fopen(f_out, "r");
            if (fo == nullptr) { remove(f_in); remove(f_out); return EXIT_FAILURE; }
            while (fgets(riga, (int)sizeof(riga), fo) != nullptr) { printf("  %s", riga); }
            fclose(fo);
            remove(f_out);
        }
    }
    remove(f_in);
    return EXIT_SUCCESS;
}

