soluzione_file.coda_inv.c:
#include "coda_inv.h"
#include <assert.h>
#include <stdckdint.h>
#include <stdlib.h>

struct coda_inv {
    int32_t *dati;
    size_t cap;
    size_t testa;
    size_t coda;
    size_t len;
};

#ifndef NDEBUG
static bool coda_invariante_ok(const coda_inv_t *q) {
    if (q == nullptr || q->dati == nullptr) { return false; }
    if (q->cap < 2 || (q->cap & (q->cap - 1)) != 0) { return false; }
    if (q->len > q->cap || q->testa >= q->cap || q->coda >= q->cap) { return false; }
    return ((q->testa + q->len) % q->cap) == q->coda;
}
#endif

static bool coda_espandi(coda_inv_t *q) {
    assert(coda_invariante_ok(q));
    size_t nuova_cap = 0, byte_tot = 0;
    if (ckd_mul(&nuova_cap, q->cap, (size_t)2) || ckd_mul(&byte_tot, nuova_cap, sizeof(*q->dati))) {
        return false;
    }
    int32_t *nuovi = malloc(byte_tot);
    if (nuovi == nullptr) { return false; }
    for (size_t i = 0; i < q->len; ++i) {
        nuovi[i] = q->dati[(q->testa + i) % q->cap];
    }
    free(q->dati);
    q->dati = nuovi;
    q->cap = nuova_cap;
    q->testa = 0;
    q->coda = q->len;
    assert(coda_invariante_ok(q));
    return true;
}

coda_inv_t *coda_crea(void) {
    coda_inv_t *q = malloc(sizeof(*q));
    if (q == nullptr) { return nullptr; }
    q->dati = malloc(2 * sizeof(*q->dati));
    if (q->dati == nullptr) { free(q); return nullptr; }
    q->cap = 2; q->testa = 0; q->coda = 0; q->len = 0;
    assert(coda_invariante_ok(q));
    return q;
}

void coda_distruggi(coda_inv_t *q) {
    if (q == nullptr) { return; }
    assert(coda_invariante_ok(q));
    free(q->dati);
    free(q);
}

bool coda_accoda(coda_inv_t *q, int32_t val) {
    if (q == nullptr) { return false; }
    assert(coda_invariante_ok(q));
    if (q->len == q->cap && !coda_espandi(q)) { return false; }
    q->dati[q->coda] = val;
    q->coda = (q->coda + 1) % q->cap;
    ++q->len;
    assert(coda_invariante_ok(q));
    return true;
}

bool coda_estrai(coda_inv_t *q, int32_t *out) {
    if (q == nullptr || q->len == 0) { return false; }
    assert(coda_invariante_ok(q));
    if (out != nullptr) { *out = q->dati[q->testa]; }
    q->testa = (q->testa + 1) % q->cap;
    --q->len;
    assert(coda_invariante_ok(q));
    return true;
}

bool coda_testa(const coda_inv_t *q, int32_t *out) {
    if (q == nullptr || out == nullptr || q->len == 0) { return false; }
    assert(coda_invariante_ok(q));
    *out = q->dati[q->testa];
    return true;
}

size_t coda_len(const coda_inv_t *q) { return (q != nullptr) ? q->len : 0; }
size_t coda_cap(const coda_inv_t *q) { return (q != nullptr) ? q->cap : 0; }

bool coda_elemento_i(const coda_inv_t *q, size_t idx, int32_t *out) {
    if (q == nullptr || out == nullptr || idx >= q->len) { return false; }
    assert(coda_invariante_ok(q));
    *out = q->dati[(q->testa + idx) % q->cap];
    return true;
}

