#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "coda_inv.h"

int main(void) {
    coda_inv_t *q = coda_crea();
    if (q == nullptr) { return EXIT_FAILURE; }
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long v = 0;
        if (strcmp(cmd, "ENQ") == 0 && sscanf(riga, "ENQ %lld %c", &v, &extra) == 1 && v >= INT32_MIN && v <= INT32_MAX) {
            if (!coda_accoda(q, (int32_t)v)) { coda_distruggi(q); return EXIT_FAILURE; }
            printf("ENQ %" PRId32 " (len=%zu, cap=%zu)\n", (int32_t)v, coda_len(q), coda_cap(q));
        } else if (strcmp(cmd, "DEQ") == 0 && sscanf(riga, "DEQ %c", &extra) != 1) {
            int32_t x = 0;
            if (coda_estrai(q, &x)) { printf("DEQ: %" PRId32 "\n", x); }
            else { printf("DEQ: VUOTA\n"); }
        } else if (strcmp(cmd, "PEEK") == 0 && sscanf(riga, "PEEK %c", &extra) != 1) {
            int32_t x = 0;
            if (coda_testa(q, &x)) { printf("PEEK: %" PRId32 "\n", x); }
            else { printf("PEEK: VUOTA\n"); }
        } else if (strcmp(cmd, "STAT") == 0 && sscanf(riga, "STAT %c", &extra) != 1) {
            printf("STAT len=%zu cap=%zu\n", coda_len(q), coda_cap(q));
        } else if (strcmp(cmd, "DUMP") == 0 && sscanf(riga, "DUMP %c", &extra) != 1) {
            printf("DUMP:");
            if (coda_len(q) == 0) { printf(" (vuota)\n"); }
            else {
                for (size_t i = 0; i < coda_len(q); ++i) {
                    int32_t x = 0; coda_elemento_i(q, i, &x); printf(" %" PRId32, x);
                }
                printf("\n");
            }
        } else { coda_distruggi(q); return EXIT_FAILURE; }
    }
    coda_distruggi(q);
    return EXIT_SUCCESS;
}

