#include "fmt_variadico.h"
#include <stdarg.h>
#include <stdint.h>
#include <stdlib.h>

char *formatta_alloc(const char *fmt, ...) {
    if (fmt == nullptr) { return nullptr; }
    va_list ap, copia;
    va_start(ap, fmt);
    va_copy(copia, ap);
    int len = vsnprintf(nullptr, 0, fmt, copia);
    va_end(copia);
    if (len < 0) {
        va_end(ap);
        return nullptr;
    }
    char *buf = malloc((size_t)len + 1);
    if (buf == nullptr) {
        va_end(ap);
        return nullptr;
    }
    int scritti = vsnprintf(buf, (size_t)len + 1, fmt, ap);
    va_end(ap);
    if (scritti < 0) {
        free(buf);
        return nullptr;
    }
    return buf;
}

void log_su_stream(FILE *out, const char *tag, const char *fmt, ...) {
    if (out == nullptr || tag == nullptr || fmt == nullptr) { return; }
    fprintf(out, "[%s] ", tag);
    va_list ap;
    va_start(ap, fmt);
    vfprintf(out, fmt, ap);
    va_end(ap);
    fputc('\n', out);
}

bool riepilogo_tipato(const char *spec, double *somma_out, size_t *cont_out, ...) {
    if (spec == nullptr || somma_out == nullptr || cont_out == nullptr) { return false; }
    va_list ap;
    va_start(ap, cont_out);
    double somma = 0.0;
    size_t cont = 0;
    bool ok = true;
    for (const char *p = spec; *p != '\0'; ++p) {
        if (*p == 'i') {
            somma += (double)va_arg(ap, int);
        } else if (*p == 'l') {
            somma += (double)va_arg(ap, int64_t);
        } else if (*p == 'd') {
            somma += va_arg(ap, double);
        } else if (*p == 'b') {
            somma += (va_arg(ap, int) != 0) ? 1.0 : 0.0;
        } else {
            ok = false;
            break;
        }
        ++cont;
    }
    va_end(ap);
    if (ok) {
        *somma_out = somma;
        *cont_out = cont;
    }
    return ok;
}

