#ifndef DIAGNOSTICA_H
#define DIAGNOSTICA_H

#include <stddef.h>
#include <stdint.h>

#define ARRAY_LEN(arr) (sizeof(arr) / sizeof((arr)[0]))
#define VERIFICA_PASSO(reg, cond, codice) \
    diag_registra((reg), (cond), (codice), __FILE__, __LINE__, __func__)

static inline int32_t satura_i32(int32_t x, int32_t lo, int32_t hi) {
    if (x < lo) { return lo; }
    if (x > hi) { return hi; }
    return x;
}

typedef struct registro_diag {
