#include "diagnostica.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char *nome_base(const char *path) {
    if (path == nullptr) { return "sconosciuto"; }
    const char *s1 = strrchr(path, '/');
    const char *s2 = strrchr(path, '\\');
    const char *sep = (s1 > s2) ? s1 : s2;
    return (sep != nullptr) ? (sep + 1) : path;
}

static void copia_troncata(char *dst, size_t cap, const char *src) {
    if (src == nullptr) { src = ""; }
    size_t len = strlen(src);
    if (len >= cap) { len = cap - 1; }
    memcpy(dst, src, len);
    dst[len] = '\0';
}

[[nodiscard]] bool diag_registra(registro_diag_t *reg, bool cond, int codice, const char *file, int riga, const char *func) {
    if (reg == nullptr) { return false; }
    if (cond) {
        ++reg->ok;
        return true;
    }
    if (reg->falliti == 0) {
        reg->primo_codice_err = codice;
        reg->prima_riga_err = riga;
        copia_troncata(reg->primo_file, sizeof(reg->primo_file), nome_base(file));
        copia_troncata(reg->prima_func, sizeof(reg->prima_func), func);
    }
    ++reg->falliti;
    return false;
}

[[nodiscard]] bool diag_stampa_riepilogo(const registro_diag_t *reg, [[maybe_unused]] const char *etichetta_debug) {
    if (reg == nullptr) { return false; }
    const char *f = (reg->falliti > 0) ? reg->primo_file : "nessuno";
    const char *fn = (reg->falliti > 0) ? reg->prima_func : "nessuna";
    const char *rv = (reg->prima_riga_err > 0) ? "SI" : "NO";
    return printf("REPORT: ok=%zu falliti=%zu primo_err=%d file=%s func=%s riga_valida=%s\n",
                  reg->ok, reg->falliti, reg->primo_codice_err, f, fn, rv) >= 0;
}

[[noreturn]] void diag_errore_fatale(const char *motivo, const char *file, int riga) {
    fprintf(stderr, "ERRORE FATALE (%s:%d): %s\n", nome_base(file), riga, (motivo != nullptr) ? motivo : "");
    exit(EXIT_FAILURE);
}

