#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "diagnostica.h"

static bool esegui_verifica(registro_diag_t *reg, int32_t val, int32_t lo, int32_t hi) {
    return VERIFICA_PASSO(reg, val >= lo && val <= hi, 101);
}

int main(void) {
    const int32_t soglie[] = {10, 20, 30, 40, 50};
    registro_diag_t reg = {};
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long v = 0, lo = 0, hi = 0;
        if (strcmp(cmd, "ARRAY") == 0 && sscanf(riga, "ARRAY %c", &extra) != 1) {
            printf("ARRAY_LEN: %zu\n", ARRAY_LEN(soglie));
        } else if (strcmp(cmd, "CHECK") == 0 && sscanf(riga, "CHECK %lld %lld %lld %c", &v, &lo, &hi, &extra) == 3) {
            bool ok = esegui_verifica(&reg, (int32_t)v, (int32_t)lo, (int32_t)hi);
            printf("CHECK %" PRId32 " [%" PRId32 "..%" PRId32 "]: %s\n", (int32_t)v, (int32_t)lo, (int32_t)hi, ok ? "OK" : "FALLITO");
        } else if (strcmp(cmd, "CLAMP") == 0 && sscanf(riga, "CLAMP %lld %lld %lld %c", &v, &lo, &hi, &extra) == 3 && lo <= hi) {
            int32_t c = (int32_t)v;
            int32_t r = satura_i32(++c, (int32_t)lo, (int32_t)hi);
            if (v < 0) {
                printf("CLAMP(++(%lld), %" PRId32 ", %" PRId32 ") -> %" PRId32 " (c=%" PRId32 ")\n", v, (int32_t)lo, (int32_t)hi, r, c);
            } else {
                printf("CLAMP(++%lld, %" PRId32 ", %" PRId32 ") -> %" PRId32 " (c=%" PRId32 ")\n", v, (int32_t)lo, (int32_t)hi, r, c);
            }
        } else if (strcmp(cmd, "REPORT") == 0 && sscanf(riga, "REPORT %c", &extra) != 1) {
            if (!diag_stampa_riepilogo(&reg, "debug_main")) {
                diag_errore_fatale("errore di stampa", __FILE__, __LINE__);
            }
        } else {
            diag_errore_fatale("comando non valido", __FILE__, __LINE__);
        }
    }
    return EXIT_SUCCESS;
}

