#include <inttypes.h>
#include <signal.h>
#include <stdckdint.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static volatile sig_atomic_t stato_segnale = 0;

static void gestore_arresto(int sig) {
    stato_segnale = (sig == SIGINT) ? 1 : 2;
    (void)signal(sig, gestore_arresto);
}

static bool aggiungi_risultato(int32_t **arr, size_t *len, size_t *cap, int32_t val) {
    if (*len == *cap) {
        size_t nuova = (*cap == 0) ? 4 : (*cap * 2);
        size_t byte_tot = 0;
        if (ckd_mul(&byte_tot, nuova, sizeof(**arr))) { return false; }
        int32_t *tmp = realloc(*arr, byte_tot);
        if (tmp == nullptr) { return false; }
        *arr = tmp;
        *cap = nuova;
    }
    (*arr)[(*len)++] = val;
    return true;
}

int main(void) {
    if (signal(SIGINT, gestore_arresto) == SIG_ERR || signal(SIGTERM, gestore_arresto) == SIG_ERR) {
        fprintf(stderr, "Errore nella registrazione dei gestori di segnale.\n");
        return EXIT_FAILURE;
    }
    int32_t *risultati = nullptr;
    size_t len = 0, cap = 0;
    char riga[128], cmd[24], extra = '\0';

    while (stato_segnale == 0 && fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        int id = 0;
        long long a = 0, b = 0;
        if (strcmp(cmd, "WORK") == 0 && sscanf(riga, "WORK %d %lld %lld %c", &id, &a, &b, &extra) == 3 &&
            a >= INT32_MIN && a <= INT32_MAX && b >= INT32_MIN && b <= INT32_MAX) {
            int32_t somma = 0;
            if (ckd_add(&somma, (int32_t)a, (int32_t)b)) {
                printf("WORK %d: OVERFLOW EVITATO\n", id);
            } else {
                if (!aggiungi_risultato(&risultati, &len, &cap, somma)) {
                    free(risultati);
                    return EXIT_FAILURE;
                }
                printf("WORK %d: %" PRId32 "\n", id, somma);
            }
        } else if (strcmp(cmd, "IGNORA_TERM") == 0 && sscanf(riga, "IGNORA_TERM %c", &extra) != 1) {
            if (signal(SIGTERM, SIG_IGN) == SIG_ERR) { free(risultati); return EXIT_FAILURE; }
            printf("SIGTERM: IGNORATO\n");
        } else if (strcmp(cmd, "RIATTIVA_TERM") == 0 && sscanf(riga, "RIATTIVA_TERM %c", &extra) != 1) {
            if (signal(SIGTERM, gestore_arresto) == SIG_ERR) { free(risultati); return EXIT_FAILURE; }
            printf("SIGTERM: GESTITO\n");
        } else if (strcmp(cmd, "RAISE_INT") == 0 && sscanf(riga, "RAISE_INT %c", &extra) != 1) {
            if (raise(SIGINT) != 0) { free(risultati); return EXIT_FAILURE; }
        } else if (strcmp(cmd, "RAISE_TERM") == 0 && sscanf(riga, "RAISE_TERM %c", &extra) != 1) {
            if (raise(SIGTERM) != 0) { free(risultati); return EXIT_FAILURE; }
            if (stato_segnale == 0) { printf("Dopo RAISE_TERM: ancora attivo\n"); }
        } else {
            free(risultati);
            return EXIT_FAILURE;
        }
    }
    (void)signal(SIGINT, SIG_DFL);
    (void)signal(SIGTERM, SIG_DFL);
    int64_t somma_tot = 0;
    for (size_t i = 0; i < len; ++i) {
        somma_tot += risultati[i];
    }
    const char *causa = "EOF";
    if (stato_segnale == 1) { causa = "SIGINT"; }
    else if (stato_segnale == 2) { causa = "SIGTERM"; }
    printf("Arresto: %s (completati=%zu, somma=%" PRId64 ")\n", causa, len, somma_tot);
    free(risultati);
    return EXIT_SUCCESS;
}
